create or replace function public.get_owner_behavioral_insights(p_days integer default 30) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare d integer:=least(greatest(coalesce(p_days,30),1),90); result jsonb; begin if auth.uid() is null or not public.is_platform_owner() then raise exception 'Owner access required'; end if; select jsonb_build_object('returning_visitors',(select count(*)::integer from (select visitor_id from public.site_analytics_events where created_at>=now()-make_interval(days=>d) and visitor_id is not null group by visitor_id having count(distinct created_at::date)>1) x),'repeat_tool_users',(select count(*)::integer from (select visitor_id from public.site_analytics_events where created_at>=now()-make_interval(days=>d) and event_name='tool_start' and visitor_id is not null group by visitor_id having count(*)>1) x),'tool_funnels',coalesce((select jsonb_agg(to_jsonb(x) order by x.starts desc) from (select event_label as tool,count(*) filter(where event_name='tool_start')::integer as starts,count(*) filter(where event_name='tool_complete')::integer as completions,round(100.0*count(*) filter(where event_name='tool_complete')/nullif(count(*) filter(where event_name='tool_start'),0),1) as completion_percent from public.site_analytics_events where created_at>=now()-make_interval(days=>d) and event_name in ('tool_start','tool_complete') group by event_label) x),'[]'::jsonb)) into result; return result; end; $$; revoke all on function public.get_owner_behavioral_insights(integer) from public; grant execute on function public.get_owner_behavioral_insights(integer) to authenticated;